const W=46,H=34,T=32,SAVE='loophole-save-v1';let state=null,screen='title',selected=[],battle=null,keys={},lastMove=0,lastFrame=0,frame=0,audioOn=false,audioCtx=null,toastTimer,animId,modalStack=[];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const rng=(x,y)=>{const n=Math.sin(x*127.1+y*311.7)*43758.5453;return n-Math.floor(n)};
function tile(x,y){if(x<0||y<0||x>=W||y>=H)return 0;const edge=Math.min(x,y,W-1-x,H-1-y);if(edge<2||(edge<4&&rng(x>>1,y>>1)<.5))return 0;const p=POINTS.some(p=>Math.abs(p.x-x)<=1&&Math.abs(p.y-y)<=1);const road=Math.abs(y-23)<1&&x>=7&&x<=37||Math.abs(x-24)<1&&y>=8&&y<=28||Math.abs(y-8)<1&&x>=6&&x<=38||Math.abs(x-6)<1&&y>=6&&y<=23||Math.abs(x-37)<1&&y>=8&&y<=28||Math.abs(y-28)<1&&x>=24&&x<=37||y===15&&x>=23&&x<=25;if(p||road)return 2;if(x>18&&x<22&&y>3&&y<21&&y!==8&&y!==15)return 0;if(rng(x,y)>.91)return 3;return 1}
function region(x,y){if(x>29&&y>21)return 'The Ashen March';if(x>26&&y<16)return 'The Glasslands';if(x<18&&y<17)return 'The Briarwood';if(Math.abs(x-24)<5&&Math.abs(y-15)<5)return 'The Still Hour';return 'Stillwater Vale'}
function infoButton(title,text){return `<button class="info" data-action="info" data-title="${esc(title)}" data-text="${esc(text)}" aria-label="Information about ${esc(title)}">i</button>`}
function action(label,act,detail,cls='btn',disabled=false){return `<div class="info-wrap"><button class="${cls}" data-action="${act}" ${disabled?'disabled':''}>${label}</button>${infoButton(label.replace(/<[^>]*>/g,''),detail)}</div>`}
function toast(t){clearTimeout(toastTimer);$('#toast').textContent=t;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3200)}
function sound(kind='click'){if(!audioOn)return;try{audioCtx??=new(window.AudioContext||window.webkitAudioContext)();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.connect(g);g.connect(audioCtx.destination);o.type='sine';o.frequency.setValueAtTime(kind==='win'?660:kind==='hit'?155:440,audioCtx.currentTime);o.frequency.exponentialRampToValueAtTime(kind==='win'?990:220,audioCtx.currentTime+.15);g.gain.setValueAtTime(.055,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+.25);o.start();o.stop(audioCtx.currentTime+.25)}catch{}}
function stats(){const c=state.classes.map(i=>CLASSES[i]);return {maxHp:86+c.reduce((s,a)=>s+a.hp,0)+(state.level-1)*14,maxMp:32+c.reduce((s,a)=>s+a.mag,0)+(state.level-1)*5,atk:10+c.reduce((s,a)=>s+a.atk,0)+(state.level-1)*3+state.weapon*4,mag:8+c.reduce((s,a)=>s+a.mag,0)+(state.level-1)*3+state.weapon*2,def:3+c.reduce((s,a)=>s+a.def,0)+(state.level-1)*2+state.armor*3}}
function title(){stopTouchMove();screen='title';battle=null;keys={};closeAll();app.innerHTML=`<main class="title-screen"><header><div class="wordmark">L<span>◌</span>OPHOLE</div><div class="header-note">A TALE BETWEEN SECONDS</div><button class="btn" data-action="sound">Sound ${audioOn?'on':'off'} ♫</button></header><div class="title-content"><section class="title-copy"><div class="eyebrow">An adventure beyond the hour</div><h1>Loophole<span style="color:var(--gold)">.</span></h1><div class="title-sub">The Fractured Hour</div><p>The clocks have stopped. The forest remembers.<br>Find the space between moments —<br>and bring the world back to tomorrow.</p><nav class="title-menu" aria-label="Main menu">${action('New journey <span>↗</span>','new','Create a hero with any two of eight classes. Picking the same class twice grants 30% stronger class skills.','btn primary')}${action('Load game <span>→</span>','load','Continue the game saved in this browser.','btn',!hasSave())}${action('Exit <span>↗</span>','exit','Open the exit screen. You can then close this browser tab.')}</nav><div class="small muted" style="margin-top:30px">8 disciplines &nbsp; · &nbsp; 1 fractured world &nbsp; · &nbsp; your way through</div></section><section class="title-art"><canvas id="title-canvas" width="640" height="720" aria-label="Pixel art of a broken clocktower on a forest island"></canvas><div class="art-caption"><span>THE STILLWATER ARCHIPELAGO</span><span>EST. BEFORE TIME</span></div></section></div><footer><span>A SMALL WORLD. AN IMPOSSIBLE HOUR.</span><span>KEYBOARD · MOUSE · TOUCH</span><span>LOOP 001 / ∞</span></footer></main>`;drawTitle()}
function hasSave(){try{return !!localStorage.getItem(SAVE)}catch{return false}}
function creation(){screen='creation';closeAll();app.innerHTML=`<header><button class="wordmark" data-action="title">L<span>◌</span>OPHOLE</button><div class="eyebrow">01 / Become someone</div><button class="btn" data-action="title">← Back</button></header><main class="creation"><div class="eyebrow">Two disciplines. One possibility.</div><h1 class="creation-title">Who will you be this time?</h1><p class="muted small">Choose two classes. Combine their strengths, or choose one twice for 30% stronger skills.<br>Click a selected class again to specialize. Use Reset to start over.</p><div class="class-grid">${CLASSES.map((c,i)=>`<article class="class-card info-wrap ${selected.includes(i)?'selected':''}"><button class="choose" data-action="class:${i}"><div class="class-icon">${c.icon}</div><h3>${c.name} ${selected.filter(v=>v===i).length?`<span class="small">×${selected.filter(v=>v===i).length}</span>`:''}</h3><p>${c.role}</p></button>${infoButton(c.name,c.desc)}</article>`).join('')}</div><div class="selection-footer"><div class="stack"><div class="row"><span class="slot">${selected[0]!==undefined?CLASSES[selected[0]].name:'First discipline'}</span><span class="muted">+</span><span class="slot">${selected[1]!==undefined?CLASSES[selected[1]].name:'Second discipline'}</span><button class="small muted" data-action="reset-classes">Reset</button></div><label class="small muted">Your name &nbsp; <input class="name-input" id="hero-name" maxlength="22" placeholder="Wanderer" aria-label="Character name"></label></div><button class="btn primary" data-action="begin" ${selected.length!==2?'disabled':''}>Step into the hour →</button></div></main>`}
function begin(){const name=$('#hero-name').value.trim()||'Wanderer';state={version:1,name,classes:[...selected],x:8,y:24,level:1,xp:0,ultimates:{},gold:35,hp:1,mp:1,weapon:0,armor:0,items:{potion:5,ether:3,herb:2,ore:2,crystal:0},seals:[],chests:[],seen:[],kills:0,steps:0,won:false,log:['You arrived at Stillwater Refuge.'],playtime:0};const s=stats();state.hp=s.maxHp;state.mp=s.maxMp;world();dialogue('Mira, keeper of the refuge','You remember arriving. You don’t remember from where. Every hour the island begins again — except for us. Three guardians hold the hour seals. Bring them to the Clocktower, and we might finally see the dawn.',[{label:'I’ll find the seals',fn:()=>{closeAll();toast('Follow the road north to the Verdant Shrine. Use Interact near a landmark.')}}])}
function bars(){const s=stats();return `<div class="bar-label"><span>VITALITY</span><span>${state.hp} / ${s.maxHp}</span></div><div class="bar"><i style="width:${state.hp/s.maxHp*100}%"></i></div><div class="bar-label"><span>AETHER</span><span>${state.mp} / ${s.maxMp}</span></div><div class="bar mp"><i style="width:${state.mp/s.maxMp*100}%"></i></div><div class="xp-wrap"><div class="bar-label"><span>LEVEL ${state.level}</span><span>${state.xp} / ${nextXp()} XP</span></div><div class="bar xp"><i style="width:${state.xp/nextXp()*100}%"></i></div></div>`}
function quest(){return state.won?['A new tomorrow','The hour is yours. Explore, craft, and remember.']:state.seals.length===3?['Break the loop','Enter the Clocktower in the center of the island.']:['Gather the hour seals',`${state.seals.length} of 3 recovered. ${['Seek the Verdant Shrine in the northwest.','Seek the Glass Observatory in the northeast.','Seek Ember Keep in the southeast.'][state.seals.includes(0)?state.seals.includes(1)?2:1:0]}`]}
function world(){stopTouchMove();screen='world';app.innerHTML=`<main class="game"><header><button class="wordmark" data-action="menu">L<span>◌</span>OPHOLE</button><div class="header-note">THE FRACTURED HOUR</div><div class="top-actions"><button class="btn" data-action="map">Map <span class="small muted">M</span></button><button class="btn" data-action="menu">☰ &nbsp; Menu <span class="small muted">Esc</span></button></div></header><div class="game-body"><section class="world-panel"><canvas id="world" aria-label="Explore the island using the movement buttons, WASD, or arrow keys. Use Interact near landmarks."></canvas><div class="location-tag"><div class="eyebrow">The Stillwater Archipelago</div><h2 id="location">${region(state.x,state.y)}</h2></div><div class="world-help"><span><kbd class="key">W A S D</kbd> <span class="small">or arrows to move</span></span><button class="btn" data-action="interact">Interact <kbd class="key">E</kbd></button></div><div id="combat-slot"></div></section>${mobileControls()}<aside class="sidebar" id="sidebar"></aside></div><footer class="game-footer"><span id="footer-status">THE HOUR IS STILL. YOU ARE NOT.</span><span class="keyboard-hint">WASD / ARROWS · E INTERACT · M MAP · ESC MENU</span><span class="touch-hint">HOLD ARROWS TO MOVE · TAP INTERACT NEAR LANDMARKS</span><button data-action="help">How to play ↗</button></footer></main>`;updateSidebar();updateTouchPrompt();resize();if(battle)renderBattle()}
function updateSidebar(){if(!$('#sidebar'))return;const q=quest();$('#sidebar').innerHTML=`<section><div class="eyebrow">The wanderer</div><h2 class="hero-name">${esc(state.name)}</h2><div class="class-label">${state.classes.map(i=>CLASSES[i].name).join(' + ')}</div><div id="hero-bars">${bars()}</div></section><div class="divider"></div><section><div class="eyebrow">Your next chapter</div><div class="quest"><h3>${q[0]}</h3><p class="small muted">${q[1]}</p></div><div class="seals">${['♧','◇','♜'].map((s,i)=>`<span class="seal ${state.seals.includes(i)?'found':''}" title="${['Verdant','Azure','Ember'][i]} Seal">${s}</span>`).join('')}</div></section><div class="divider"></div><section class="journal-section"><div class="row between"><span class="eyebrow">In your pocket</span><span style="color:var(--gold)">${state.gold} <span class="small">G</span></span></div><button class="small muted" style="margin-top:14px" data-action="inventory">${state.items.potion} draughts &nbsp; · &nbsp; ${state.items.ether} flasks &nbsp; ↗</button></section><section class="log-section" style="margin-top:auto"><div class="eyebrow" style="margin-bottom:14px">Echoes of the hour</div><div class="log">${state.log.slice(-3).reverse().map(t=>`<p>${esc(t)}</p>`).join('')}</div></section>`}
function log(t){state.log.push(t);if(state.log.length>30)state.log.shift();updateSidebar()}
function modal(title,body){stopTouchMove();keys={};if(modalStack.length)modalStack.at(-1).inert=true;app.inert=true;const el=document.createElement('div');el.className='overlay-backdrop';el.innerHTML=`<section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><h2>${title}</h2><button class="close" data-action="close" aria-label="Close">×</button></div><div class="modal-body">${body}</div></section>`;el.returnFocus=document.activeElement;layers.append(el);modalStack.push(el);el.querySelector('button')?.focus();return el}
function close(){const m=modalStack.pop();if(m){m.remove();if(modalStack.length)modalStack.at(-1).inert=false;else app.inert=false;if(m.returnFocus?.isConnected)m.returnFocus.focus()}}
function closeAll(){modalStack=[];layers.innerHTML='';app.inert=false}
function dialogue(speaker,copy,actions){const m=modal(speaker,`<div class="dialogue-speaker">${speaker}</div><div class="dialogue-copy">${copy}</div><div class="dialogue-actions"></div>`);for(const a of actions){const b=document.createElement('button');b.className='btn '+(a.primary===false?'':'primary');b.textContent=a.label;b.onclick=a.fn;m.querySelector('.dialogue-actions').append(b)}}
function menu(){if(!state)return;const options=[['Inventory','inventory','Use healing items and view your crafting materials.'],['Equipment','equipment','Inspect and upgrade your weapon and armor.'],['Character Leveling','leveling','View your attributes, experience and class skills.'],['Crafting','crafting','Combine materials into healing items or permanent equipment upgrades.'],['Bestiary','bestiary','Read about every creature you have encountered.'],['Save Game','save-menu','Save your current progress to this browser, or export a backup.'],['Leave Game','leave','Return to the title screen. You can save before leaving.'],['How to play','help','Controls, battle rules, class mastery, and your objective.']];modal('A moment to yourself',`<div class="eyebrow" style="margin-bottom:22px">${battle?'In battle':'On the road'} · Level ${state.level} · ${state.gold} gold</div><div class="menu-list">${options.map(([n,a,d],i)=>action(`<span class="menu-number">0${i+1}</span>${n}`,a,d,'')).join('')}</div>`)}
function inventory(){modal('Inventory',`<p class="small muted" style="margin-bottom:22px">Supplies for the road. Using an item in battle takes your turn.</p>${Object.entries(ITEMS).map(([id,it])=>`<div class="item-row"><div><h3><span style="color:var(--gold)">${it.icon}</span> ${it.name}</h3><p>${it.desc}</p></div><div class="item-actions"><span>×${state.items[id]}</span>${['potion','ether'].includes(id)?`<button class="btn" data-action="use:${id}" ${!state.items[id]||battle?.busy?'disabled':''}>Use</button>`:''}${infoButton(it.name,it.desc)}</div></div>`).join('')}`)}
function useItem(id){if(!state.items[id]||battle?.busy)return;const s=stats();if(id==='potion'&&state.hp===s.maxHp||id==='ether'&&state.mp===s.maxMp){toast('Already full. Save this for later.');return}state.items[id]--;if(id==='potion')state.hp=Math.min(s.maxHp,state.hp+60);else state.mp=Math.min(s.maxMp,state.mp+25);sound();log(`Used ${ITEMS[id].name}.`);if(battle){closeAll();endTurn('You drink a '+ITEMS[id].name+'.')}else{close();inventory()}}
function equipment(){const s=stats();modal('Equipment',`<p class="small muted">Forged upgrades are permanent and improve every discipline. Visit Crafting to make them.</p><div class="item-row"><div><h3>◇ ${['Traveler’s Blade','Ironbound Blade','Runic Blade','Hourglass Blade'][state.weapon]}</h3><p>Weapon tier ${state.weapon} / 3 · +${state.weapon*4} attack · +${state.weapon*2} magic</p></div>${infoButton('Weapon','Each tier adds 4 physical attack and 2 magic. All classes can use this weapon.')}</div><div class="item-row"><div><h3>⛨ ${['Wayfarer’s Coat','Ironweave Coat','Runic Mantle','Hourglass Mantle'][state.armor]}</h3><p>Armor tier ${state.armor} / 3 · +${state.armor*3} defense</p></div>${infoButton('Armor','Each tier adds 3 defense, reducing incoming physical damage.')}</div><div class="stats"><div class="stat">Attack<strong>${s.atk}</strong></div><div class="stat">Magic<strong>${s.mag}</strong></div><div class="stat">Defense<strong>${s.def}</strong></div></div><button class="btn primary" style="margin-top:24px" data-action="crafting">Open crafting →</button>`)}
function nextXp(){return state.level*40}
function ultimateFor(classId){const choice=state.ultimates?.[classId];return state.level>=5&&(choice===0||choice===1)?ULTIMATES[classId]?.[choice]:null}
function ultimateChoices(){const unlocked=state.level>=5;return `<section class="ultimate-section"><div class="row between"><div><div class="eyebrow">${unlocked?'Level 5 · unlocked':'Unlocks at level 5'}</div><h3 style="margin-top:8px">Your ultimate abilities</h3></div><span class="pill">${unlocked?'✦':'⌑'} ${unlocked?'Choose your path':'Level '+state.level+' / 5'}</span></div><p class="small muted" style="margin:14px 0 24px">Choose one ultimate for each of your classes. Each can be used once per battle and takes a turn. You can change your choices between battles. ${state.classes[0]===state.classes[1]?'Your specialist mastery makes your ultimate 30% stronger.':''}${battle?' Finish this battle to choose or change an ultimate.':''}</p>${[...new Set(state.classes)].map(i=>`<div class="ultimate-class"><div class="eyebrow">${CLASSES[i].icon} ${CLASSES[i].name}</div><div class="ultimate-grid">${ULTIMATES[i].map((u,j)=>{const picked=state.ultimates?.[i]===j;return `<article class="ultimate-card ${picked?'selected':''}"><div class="row between"><span class="eyebrow">${u.cost} AP · Once per battle</span>${infoButton(u.name,u.desc)}</div><h3>${u.name}</h3><p class="small muted">${u.desc}</p><button class="btn ${picked?'':'primary'}" data-action="choose-ultimate:${i}:${j}" ${!unlocked||battle||picked?'disabled':''}>${picked?'✓ Selected':unlocked?'Choose '+u.name:'Unlock at level 5'}</button></article>`}).join('')}</div></div>`).join('')}</section>`}
function chooseUltimate(classId,choice){if(state.level<5||battle||!state.classes.includes(classId)||!Number.isInteger(choice)||!ULTIMATES[classId]?.[choice])return;state.ultimates??={};if(state.ultimates[classId]===choice)return;state.ultimates[classId]=choice;sound('win');log('Ultimate chosen: '+ULTIMATES[classId][choice].name+'.');saveGame();close();leveling();toast(ULTIMATES[classId][choice].name+' is ready for your next battle.')}
function leveling(){const s=stats(),master=state.classes[0]===state.classes[1];modal('Character Leveling',`<div class="row between"><div><div class="eyebrow">Level ${state.level}</div><h2>${esc(state.name)}</h2></div><div class="small muted">${state.xp} / ${nextXp()} XP to next level</div></div><p class="small muted" style="margin-top:14px">Leveling is automatic: each level grants 14 health, 5 mana, 3 attack, 3 magic and 2 defense. Health and mana refill on level-up.</p><div class="stats">${Object.entries({Vitality:s.maxHp,Aether:s.maxMp,Attack:s.atk,Magic:s.mag,Defense:s.def,'Enemies defeated':state.kills}).map(([n,v])=>`<div class="stat">${n}<strong>${v}</strong></div>`).join('')}</div>${ultimateChoices()}<div class="eyebrow" style="margin:26px 0 15px">${master?'Specialist mastery · 30% stronger skills':'Your disciplines'}</div>${[...new Set(state.classes)].map(i=>`<div class="item-row"><div><h3>${CLASSES[i].icon} ${CLASSES[i].name}</h3><p>${CLASSES[i].desc}</p></div></div>`).join('')}`)}

const recipes=[{id:'potion',name:'Healing Draught',desc:'Restore 60 health.',need:{herb:2},gold:0},{id:'ether',name:'Aether Flask',desc:'Restore 25 mana.',need:{crystal:2},gold:0},{id:'weapon',name:'Improve weapon',desc:'+4 attack and +2 magic per tier.',need:{ore:3},gold:25},{id:'armor',name:'Improve armor',desc:'+3 defense per tier.',need:{ore:2,herb:1},gold:20}];
function crafting(){modal('Crafting',`<p class="small muted" style="margin-bottom:22px">${state.gold} gold · ${state.items.herb} moonleaf · ${state.items.ore} iron shards · ${state.items.crystal} crystals</p>${recipes.map(r=>{const max=['weapon','armor'].includes(r.id)&&state[r.id]>=3,can=!max&&state.gold>=r.gold&&Object.entries(r.need).every(([k,v])=>state.items[k]>=v);return `<div class="item-row"><div><h3>${r.name}${['weapon','armor'].includes(r.id)?` <span class="small muted">Tier ${state[r.id]}/3</span>`:''}</h3><p>${r.desc}</p><p style="color:var(--gold)">${Object.entries(r.need).map(([k,v])=>`${v} ${ITEMS[k].name}`).join(' + ')}${r.gold?' + '+r.gold+' G':''}</p></div><div class="item-actions"><button class="btn" data-action="craft:${r.id}" ${!can?'disabled':''}>${max?'Maxed':'Craft'}</button>${infoButton(r.name,r.desc)}</div></div>`}).join('')}`)}
function craft(id){const r=recipes.find(r=>r.id===id);if(!r||state.gold<r.gold||Object.entries(r.need).some(([k,v])=>state.items[k]<v)||['weapon','armor'].includes(id)&&state[id]>=3)return;if(battle){toast('Finish this battle before crafting.');return}for(const[k,v]of Object.entries(r.need))state.items[k]-=v;state.gold-=r.gold;if(id==='weapon'||id==='armor')state[id]++;else state.items[id]++;sound('win');log('Crafted: '+r.name+'.');close();crafting()}
function bestiary(){modal('Bestiary',`<p class="small muted" style="margin-bottom:20px">${state.seen.length} of ${Object.keys(ENEMIES).length} creatures discovered.</p>${Object.entries(ENEMIES).map(([id,e])=>state.seen.includes(id)?`<div class="item-row"><div><h3 style="color:${e.color}">${e.name}</h3><p>${e.desc}</p><p>Vitality ${e.hp} · Attack ${e.atk} · Defense ${e.def}</p></div>${infoButton(e.name,e.desc)}</div>`:`<div class="item-row"><div><h3 class="muted">Undiscovered echo</h3><p>Continue exploring the island.</p></div><span class="muted">?</span></div>`).join('')}`)}
function saveGame(){try{localStorage.setItem(SAVE,JSON.stringify(state));toast('Journey saved in this browser.');return true}catch{toast('Browser storage unavailable. Use Export backup instead.');return false}}
function saveMenu(){modal('Save your journey',`<p class="muted">Save to this browser or download a backup to keep your journey safe.</p><p class="small muted" style="margin-top:12px">${battle?'Finish this battle before saving.':'One save slot. Saving replaces your previous browser save.'} Progress also saves after guardian victories and resting.</p><div class="dialogue-actions"><button class="btn primary" data-action="save" ${battle?'disabled':''}>Save game</button><button class="btn" data-action="export" ${battle?'disabled':''}>Export backup ↓</button><button class="btn" data-action="import" ${battle?'disabled':''}>Import backup ↑</button></div>`)}
function validUltimates(s){return s.ultimates===undefined||s.ultimates!==null&&typeof s.ultimates==='object'&&!Array.isArray(s.ultimates)&&Object.entries(s.ultimates).every(([id,choice])=>/^[0-7]$/.test(id)&&s.classes.includes(Number(id))&&s.level>=5&&(choice===0||choice===1))}
function validSave(s){const int=(v,min,max)=>Number.isInteger(v)&&v>=min&&v<=max;return s&&s.version===1&&typeof s.name==='string'&&s.name.length<=22&&Array.isArray(s.classes)&&s.classes.length===2&&s.classes.every(i=>int(i,0,7))&&int(s.x,0,W-1)&&int(s.y,0,H-1)&&tile(s.x,s.y)!==0&&int(s.level,1,999)&&int(s.xp,0,999999)&&int(s.hp,0,99999)&&int(s.mp,0,99999)&&int(s.gold,0,99999999)&&int(s.weapon,0,3)&&int(s.armor,0,3)&&s.items&&Object.keys(ITEMS).every(k=>int(s.items[k],0,999999))&&Array.isArray(s.seals)&&s.seals.every(i=>int(i,0,2))&&new Set(s.seals).size===s.seals.length&&Array.isArray(s.chests)&&s.chests.every(k=>/^chest[0-3]$/.test(k))&&Array.isArray(s.seen)&&s.seen.every(k=>ENEMIES[k])&&Array.isArray(s.log)&&s.log.every(t=>typeof t==='string')&&int(s.kills,0,999999)&&int(s.steps,0,99999999)&&typeof s.won==='boolean'&&validUltimates(s)}
function loadGame(){try{const s=JSON.parse(localStorage.getItem(SAVE));if(!validSave(s))throw Error();state=s;state.ultimates??={};state.hp=Math.max(1,Math.min(stats().maxHp,state.hp));state.mp=Math.min(stats().maxMp,state.mp);battle=null;closeAll();world();toast('Welcome back, '+state.name+'.')}catch{toast('No valid save found. Begin a new journey or import a backup.');modal('Load a backup',`<p class="muted">Import a previously exported Loophole save file.</p><button class="btn primary" style="margin-top:20px" data-action="import">Import backup ↑</button>`)}}
function exportSave(){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));a.download='loophole-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Backup downloaded.')}
function importSave(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{if(input.files[0].size>100000)throw Error();const s=JSON.parse(await input.files[0].text());if(!validSave(s))throw Error();state=s;state.ultimates??={};state.hp=Math.max(1,Math.min(stats().maxHp,state.hp));state.mp=Math.min(stats().maxMp,state.mp);battle=null;closeAll();world();saveGame()}catch{toast('That file is not a valid Loophole save.')}};input.click()}
function leave(){dialogue('Leave the island?','Your journey will wait for you. Save your progress before returning to the title screen.',[{label:battle?'Stay in battle':'Save & return to title',fn:()=>{if(battle){close();return}if(saveGame())title()}},{label:'Return without saving',primary:false,fn:title},{label:'Keep playing',primary:false,fn:close}])}
function help(){modal('A traveler’s handbook',`<div class="help-grid"><div><h3>On the road</h3><p class="small muted">Move with WASD or arrow keys. Hold two keys to move diagonally. Press E or Interact near landmarks. M opens your map. Esc opens the menu or closes an overlay. On a phone or touch screen, large controls appear automatically. Tap an arrow to take one step, or hold it to keep walking. Corner arrows move diagonally. Use the Interact button near landmarks; Menu and Map are beside it. Controls stop when you lift your finger or open a menu. Roads are safe; wandering the wilds can trigger battles.</p></div><div><h3>Your journey</h3><p class="small muted">Recover the Verdant, Azure and Ember seals, then enter the central Clocktower. The map marks every destination. Return to Stillwater Refuge for a free rest, supplies, and advice. Chests contain useful resources.</p></div><div><h3>In battle</h3><p class="small muted">Choose Strike, a class skill, Guard, an item, or Flee. Guard restores 5 mana and reduces the next hit by 65%. Bosses telegraph a heavy attack every third turn. Defeat returns you safely to the refuge, costing a little gold. You keep your experience and seals.</p></div><div><h3>Your disciplines</h3><p class="small muted">Two different classes grant two skills. Picking the same class twice boosts that skill by 30%, while both class stat bonuses still apply. Gain experience to level automatically. At level 5, choose one of two ultimates per class in Character Leveling. Each costs aether and can be used once per battle. You can change your choice between battles. Specialist mastery also boosts ultimates by 30%. Craft permanent weapon and armor upgrades from found materials.</p></div></div><p class="small muted" style="margin-top:24px">Save from the menu. Resting and defeating a guardian also save automatically. Sound is optional. This adventure has an ending; you can keep exploring afterward.</p>`)}
function nearPoint(){return POINTS.find(p=>Math.max(Math.abs(p.x-state.x),Math.abs(p.y-state.y))<=1)}
function interact(){if(battle||modalStack.length)return;const p=nearPoint();if(!p){toast('Approach a shrine, chest, or refuge to interact. Open M for the map.');return}if(p.id==='village'){dialogue('Mira · Stillwater Refuge','The fire is warm. The hour is patient. Rest here as often as you need; the road north leads to the Verdant Shrine. Take the eastern road to the Glass Observatory, then south to Ember Keep.',[{label:'Rest · free',fn:()=>{state.hp=stats().maxHp;state.mp=stats().maxMp;log('Rested by the refuge fire.');close();saveGame();sound('win')}},{label:'Trade supplies',primary:false,fn:()=>shop()},{label:'Return to the road',primary:false,fn:close}]);return}if(p.id.startsWith('chest')){if(state.chests.includes(p.id)){toast('The cache is empty.');return}state.chests.push(p.id);state.items.potion+=2;state.items.ether++;state.items.ore+=2;state.items.crystal+=2;state.gold+=25;log('Found a cache: supplies, materials and 25 gold.');sound('win');toast('Found 2 draughts, 1 flask, 2 iron, 2 crystals & 25 G!');return}if(p.id==='keeper'&&state.won){toast('The clock is moving. Tomorrow belongs to everyone.');return}if(p.id==='keeper'&&state.seals.length<3){dialogue('The Clocktower','Three empty sockets frame the door. An inscription reads: “Root, reflection, and ember. Only a whole hour may pass.”',[{label:'Find the remaining seals',fn:close}]);return}const e=ENEMIES[p.id];if(state.seals.includes(e.boss)){toast('The seal is already yours. The shrine is quiet.');return}dialogue(p.name,`${p.id==='keeper'?'The three seals turn in their sockets. At the top of the tower, a figure holds the last second in its hands.':`The air grows still. ${e.name} wakes, guarding a fragment of the broken hour.`}<br><span class="small muted">${e.desc}</span>`,[{label:p.id==='keeper'?'Face the Hourkeeper':'Challenge the guardian',fn:()=>{closeAll();startBattle(p.id)}},{label:'Prepare a little longer',primary:false,fn:close}])}
function shop(){modal('The refuge exchange',`<p class="small muted">Your gold: ${state.gold} G. Mira always offers a free rest.</p>${[['potion',12],['ether',16],['herb',5],['ore',9],['crystal',7]].map(([id,price])=>`<div class="item-row"><div><h3>${ITEMS[id].name}</h3><p>${ITEMS[id].desc}</p></div><button class="btn" data-action="buy:${id}:${price}" ${state.gold<price?'disabled':''}>${price} G · Buy</button></div>`).join('')}`)}
function move(dx,dy){if(screen!=='world'||battle||modalStack.length)return;const nx=state.x+dx,ny=state.y+dy;if(!tile(nx,ny)||tile(nx,ny)===3)return;if(dx&&dy&&(tile(state.x+dx,state.y)===0||tile(state.x,state.y+dy)===0||tile(state.x+dx,state.y)===3||tile(state.x,state.y+dy)===3))return;state.x=nx;state.y=ny;state.steps++;$('#location').textContent=region(nx,ny);const p=nearPoint();$('#footer-status').textContent=p?`${wantsTouchControls()?'INTERACT':'E'} · ${p.name.toUpperCase()}`:'THE HOUR IS STILL. YOU ARE NOT.';updateTouchPrompt();if(tile(nx,ny)===1&&state.steps>12&&Math.random()<.07){const r=region(nx,ny);startBattle(r==='The Glasslands'||r==='The Ashen March'?'shade':r==='The Briarwood'?'wolf':'wisp')}}
function startBattle(id){stopTouchMove();keys={};const e=ENEMIES[id];battle={id,hp:e.hp,turn:1,poison:0,weaken:0,fortify:0,usedUltimates:[],guard:false,busy:false,token:Math.random(),note:e.boss!==undefined?'A guardian stands in your path.':'An echo crosses your path.'};if(!state.seen.includes(id))state.seen.push(id);renderBattle();updateSidebar();sound('hit')}
function renderBattle(){const slot=$('#combat-slot');if(!slot)return;$('.game')?.classList.toggle('in-combat',!!battle);resize();if(!battle){slot.innerHTML='';return}const e=ENEMIES[battle.id],b=battle;slot.innerHTML=`<section class="combat" aria-label="Turn based combat"><div class="combat-scene"><div class="enemy-status"><div class="eyebrow">${e.boss!==undefined?'Guardian of the hour':'Wild encounter'} · Turn ${b.turn}</div><h3>${e.name}</h3><div class="bar"><i style="width:${Math.max(0,b.hp)/e.hp*100}%;background:${e.color}"></i></div><span class="small muted">${Math.max(0,b.hp)} / ${e.hp} HP${b.poison?' · Poisoned':''}${b.weaken?' · Weakened':''}${b.fortify?' · Your fortification: '+b.fortify:''}</span></div><canvas class="enemy-art" id="enemy" width="96" height="96"></canvas><div class="battle-note" role="status">${b.note}</div></div><div class="battle-controls">${action('Strike <small>0 AP</small>','fight:strike','A reliable physical attack. No mana cost.','btn',b.busy)}${[...new Set(state.classes)].map(i=>action(`${CLASSES[i].skill} <small>${CLASSES[i].cost} AP</small>`,'fight:skill:'+i,CLASSES[i].desc,'btn',b.busy||state.mp<CLASSES[i].cost)).join('')}${[...new Set(state.classes)].map(i=>{const u=ultimateFor(i);return u?action(`✦ ${u.name} <small>${b.usedUltimates.includes(i)?'Spent':u.cost+' AP'}</small>`,'fight:ultimate:'+i,u.desc+' Once per battle.','btn ultimate-btn',b.busy||b.usedUltimates.includes(i)||state.mp<u.cost):''}).join('')}${action('Guard <small>+5 AP</small>','fight:guard','Reduce the next hit by 65% and recover 5 mana.','btn',b.busy)}${action('Items','battle-items','Use a draught or flask. Using an item takes a turn.','btn',b.busy)}${action('Flee','fight:flee','Escape a wild encounter. Guardians cannot be escaped.','btn',b.busy||e.boss!==undefined)}</div></section>`;drawEnemy($('#enemy').getContext('2d'),e)}
function fight(type,id){if(!battle||battle.busy||modalStack.length)return;const s=stats(),e=ENEMIES[battle.id];let damage=0,note='';if(type==='flee'){if(e.boss!==undefined)return;battle=null;renderBattle();toast('You slip between the seconds and escape.');return}if(type==='ultimate'){useUltimate(Number(id));return}if(type==='guard'){battle.guard=true;state.mp=Math.min(s.maxMp,state.mp+5);note='You brace yourself and recover 5 aether.'}else if(type==='strike'){damage=Math.max(3,s.atk-e.def+Math.floor(Math.random()*5));note=`Your strike deals ${damage} damage.`}else{const c=CLASSES[Number(id)];if(!state.classes.includes(Number(id))||!c||state.mp<c.cost)return;state.mp-=c.cost;const master=state.classes[0]===state.classes[1]?1.3:1;const phys=m=>Math.round(Math.max(5,s.atk*m-e.def)*master),magic=m=>Math.round(Math.max(5,s.mag*m-e.def*.3)*master);switch(c.type){case'palm':damage=phys(1.8);battle.weaken=3;break;case'fire':damage=magic(2.2);break;case'twin':damage=phys(2.1);break;case'poison':damage=phys(1.3);battle.poison=3;break;case'drain':damage=magic(1.8);state.hp=Math.min(s.maxHp,state.hp+Math.round(damage*.5));break;case'aegis':damage=phys(1.4);state.hp=Math.min(s.maxHp,state.hp+Math.round(12*master));battle.guard=true;break;case'chaos':damage=magic(1.6+Math.random()*1.4);break;case'heal':{const heal=Math.round((35+s.mag*1.5)*master);state.hp=Math.min(s.maxHp,state.hp+heal);note=`Mending Light restores up to ${heal} health.`;break}}if(state.classes.includes(7))state.mp=Math.min(s.maxMp,state.mp+2);if(!note)note=`${c.skill} deals ${damage} damage${c.type==='drain'?' and siphons vitality':''}.`}
 battle.hp-=damage;sound('hit');endTurn(note)}
function useUltimate(classId){if(!battle||battle.busy||modalStack.length||!state.classes.includes(classId))return;const u=ultimateFor(classId),b=battle;if(!u||b.usedUltimates.includes(classId)||state.mp<u.cost)return;const s=stats(),e=ENEMIES[b.id],master=state.classes[0]===state.classes[1]?1.3:1;
 state.mp-=u.cost;b.usedUltimates.push(classId);let damage=0;const details=[];
 if(u.sacrifice){const paid=Math.min(state.hp-1,Math.floor(state.hp*u.sacrifice));state.hp-=paid;details.push('sacrificed '+paid+' health')}
 if(u.physical||u.magic){const power=u.physical?s.atk*u.physical:s.mag*(u.magic+(u.random?Math.random()*u.random:0));const armor=u.pierce?0:e.def*(u.physical?1:.3);damage=Math.round(Math.max(5,power+(u.defense?s.def*u.defense:0)-armor)*master*(u.execute&&b.hp<=e.hp*.4?2:1));b.hp-=damage;details.push(damage+' damage')}
 if(u.heal||u.drain){const hp=state.hp;state.hp=Math.min(s.maxHp,state.hp+Math.round((u.heal?s.maxHp*u.heal*master:0)+damage*(u.drain||0)));details.push('restored '+(state.hp-hp)+' health')}
 if(u.mana)state.mp=Math.min(s.maxMp,state.mp+Math.round(u.mana*master));if(state.classes.includes(7))state.mp=Math.min(s.maxMp,state.mp+2);
 if(u.weaken)b.weaken=Math.max(b.weaken,u.weaken);if(u.poison)b.poison=Math.max(b.poison,u.poison);if(u.fortify)b.fortify=Math.max(b.fortify,u.fortify);if(u.guard)b.guard=true;
 if(u.mana)details.push('recovered aether');if(u.weaken)details.push('enemy weakened');if(u.poison)details.push('venom applied');if(u.fortify)details.push('fortified for '+u.fortify+' turns');if(u.guard)details.push('guarding');
 sound('win');endTurn(u.name+': '+details.join(', ')+'.')}
function endTurn(note){if(!battle)return;const b=battle,e=ENEMIES[b.id];if(b.poison>0){const d=Math.max(7,Math.round(e.hp*.035));b.hp-=d;b.poison--;note+=` Venom deals ${d}.`}if(b.hp<=0){winBattle();return}b.note=note;b.busy=true;renderBattle();updateSidebar();setTimeout(()=>{if(battle!==b)return;const heavy=e.boss!==undefined?b.turn%3===0:b.turn%4===0;let dmg=Math.max(2,Math.round(e.atk*(heavy?1.75:1)*(b.weaken>0?.72:1)*(b.id==='keeper'&&b.hp<e.hp/2?1.15:1))-stats().def);if(b.fortify>0){dmg=Math.max(1,Math.round(dmg*.5));b.fortify--}if(b.guard)dmg=Math.max(1,Math.round(dmg*.35));state.hp=Math.max(0,state.hp-dmg);b.guard=false;b.weaken=Math.max(0,b.weaken-1);b.turn++;b.busy=false;b.note=`${heavy?'A crushing blow':'The enemy strikes'}: ${dmg} damage. ${e.boss!==undefined&&b.turn%3===0?'It gathers power — guard now!':'Your turn.'}`;if(state.hp<=0){defeat();return}sound('hit');renderBattle();updateSidebar()},650)}
function gainXp(n){const wasLocked=state.level<5;state.xp+=n;let levels=0;while(state.xp>=nextXp()){state.xp-=nextXp();state.level++;levels++}if(levels){state.hp=stats().maxHp;state.mp=stats().maxMp;log(`Reached level ${state.level}. Vitality and aether restored.`);if(wasLocked&&state.level>=5){log('Ultimate abilities unlocked! Choose yours in Character Leveling.');toast('Level 5: choose your ultimate abilities in Character Leveling.')}}return levels}
function winBattle(){const e=ENEMIES[battle.id],id=battle.id;battle=null;state.kills++;state.gold+=e.gold;state.items[e.drop]++;const levels=gainXp(e.xp);if(e.boss!==undefined&&e.boss<3&&!state.seals.includes(e.boss)){state.seals.push(e.boss);state.items.potion+=2;state.items.ether++;state.hp=stats().maxHp;state.mp=stats().maxMp;saveGame()}if(id==='keeper'){state.won=true;saveGame();renderBattle();ending();return}renderBattle();log(`Defeated ${e.name}. +${e.xp} XP, +${e.gold} gold.`);sound('win');modal(e.boss!==undefined?'An hour reclaimed':'The echo fades',`<div class="victory"><div class="eyebrow">Victory</div><div class="sigil">${e.boss!==undefined?['♧','◇','♜'][e.boss]:'✦'}</div><h2>${e.boss!==undefined?['The Verdant Seal','The Azure Seal','The Ember Seal'][e.boss]:'A little closer to dawn.'}</h2><p>${e.name} has fallen. ${e.boss!==undefined?'The seal is yours. Your vitality and aether return. Two draughts and a flask are added to your pack.':''}</p><p style="color:var(--gold)">+${e.xp} experience &nbsp; · &nbsp; +${e.gold} gold &nbsp; · &nbsp; +1 ${ITEMS[e.drop].name}</p>${levels?`<h3>Level ${state.level} reached</h3>`:''}<button class="btn primary" data-action="close">Back to the road →</button></div>`);updateSidebar()}
function defeat(){battle=null;state.gold=Math.max(0,state.gold-Math.min(20,Math.round(state.gold*.15)));state.x=8;state.y=24;state.hp=stats().maxHp;state.mp=stats().maxMp;world();log('The refuge fire calls you back.');dialogue('Not the end of your hour','Mira finds you at the edge of the loop. “Even time gets a second chance.” Your strength returns. A little gold is lost, but your experience and seals stay with you.',[{label:'Try another way',fn:close}])}
function ending(){updateSidebar();sound('win');modal('Tomorrow, at last',`<div class="victory"><div class="eyebrow">The end of the endless hour</div><div class="sigil">☼</div><h2>The first second<br>of a new day.</h2><p>The Hourkeeper opens its hands. It had held the hour still to keep one beautiful day from ending. But a day that never ends leaves no room for another.</p><p>Across Stillwater, leaves fall. The tide turns. Mira watches a sunrise she had almost forgotten.</p><div class="ending-line">“Thank you for letting tomorrow happen.”</div><p>${esc(state.name)} · Level ${state.level}<br>${state.classes.map(i=>CLASSES[i].name).join(' + ')}<br>${state.kills} echoes laid to rest · All three seals recovered</p><button class="btn primary" data-action="close">Explore the new day →</button><p class="small">Your completed journey has been saved.</p></div>`)}
// The island is drawn tile by tile: no remote art, engine, or install required.
let camera={x:0,y:0},canvasW=960,canvasH=640;
function rect(c,x,y,w,h,color){c.fillStyle=color;c.fillRect(Math.round(x),Math.round(y),w,h)}
function tree(c,x,y,seed=0,ash=false){rect(c,x+13,y+11,6,24,'#4c4935');rect(c,x+8,y+30,17,4,'#152e29');const a=ash?['#665a47','#817056','#a38b64']:['#254b3b','#36634a','#527c54'];rect(c,x+4,y+5,24,16,a[0]);rect(c,x+8,y-5,17,28,a[0]);rect(c,x+1,y+12,29,9,a[0]);rect(c,x+7,y+1,18,14,a[1]);rect(c,x+11,y-5,10,16,a[1]);rect(c,x+5,y+12,18,5,a[1]);rect(c,x+12,y-3,8,6,a[2]);rect(c,x+7,y+9,6,4,a[2])}
function tower(c,x,y,scale=1,kind='keeper',cleared=false){c.save();c.translate(x,y);c.scale(scale,scale);const col=kind==='ash'?'#7c6861':kind==='grove'?'#6c8571':'#7d9090';rect(c,-25,18,50,9,'#18302b');rect(c,-20,-34,40,56,col);rect(c,-24,-40,48,8,'#b0b4a0');rect(c,-16,-54,32,15,col);rect(c,-20,-58,40,6,'#b8bda5');rect(c,-14,-71,7,16,'#718782');rect(c,7,-71,7,16,'#718782');rect(c,-22,17,44,7,'#bec2a7');rect(c,-7,0,14,23,'#1b3332');rect(c,-3,7,7,16,cleared?'#ddcf91':'#506d66');rect(c,-12,-29,24,23,'#1c3735');c.strokeStyle=cleared?'#e8ce8d':'#c5bc91';c.lineWidth=2;c.beginPath();c.arc(0,-17,9,0,Math.PI*2);c.stroke();c.beginPath();c.moveTo(0,-24);c.lineTo(0,-17);c.lineTo(5,-13);c.stroke();rect(c,11,-1,5,11,'#435f58');rect(c,-17,-1,5,11,'#435f58');rect(c,17,-32,3,40,'#526b5a');rect(c,-20,-26,3,11,'#526b5a');c.restore()}
function drawTile(c,x,y,t,time=0){const px=x*T,py=y*T,r=rng(x,y),ash=x>29&&y>21,glass=x>26&&y<16;const grass=ash?'#696a49':glass?'#526c59':'#476b45';if(t===0){rect(c,px,py,T,T,'#24494b');rect(c,px,py,T,3,'#315856');if((x+y)%3===0)rect(c,px+5+(Math.floor(time/40)%3)*3,py+13,12,2,'#4b7470');if(r>.6)rect(c,px+20,py+25,7,1,'#3b6461');return}rect(c,px,py,T,T,t===2?'#a09a70':grass);if(t===2){rect(c,px+4,py+6,5,2,'#ada880');rect(c,px+21,py+22,6,3,'#8c8b63');if(r>.6)rect(c,px+16,py+10,2,2,'#c1b68b')}else{if(r>.45){rect(c,px+6,py+8,2,4,'#72905b');rect(c,px+10,py+10,2,3,'#72905b')}if(r<.25){rect(c,px+22,py+21,2,3,'#8da376');rect(c,px+26,py+19,2,4,'#344e3a')}if(r>.8){rect(c,px+19,py+17,3,3,glass?'#c9d5c0':ash?'#c9b383':'#d4c893');rect(c,px+20,py+19,1,4,'#748154')}}if(t===3)tree(c,px,py,r,ash)}
function hero(c,x,y,time){rect(c,x+7,y+27,21,5,'#19382b88');const bob=Math.sin(time/8)*.6;c.save();c.translate(x+16,y+13+bob);rect(c,-6,8,4,8,'#23333c');rect(c,3,8,4,8,'#23333c');rect(c,-8,-1,16,13,'#c4a46a');rect(c,-10,0,4,9,'#ddbc85');rect(c,7,0,4,9,'#d5b67c');rect(c,-5,-10,11,11,'#dabf8e');rect(c,-6,-13,13,5,'#3b3a33');rect(c,-8,-10,5,6,'#3b3a33');rect(c,4,-6,2,2,'#253c3b');rect(c,-6,-1,13,4,'#718d89');rect(c,-6,3,4,10,'#718d89');rect(c,9,-3,3,17,'#e1d8ad');rect(c,6,7,9,3,'#75664a');c.restore()}
function drawWorld(){const c=$('#world')?.getContext('2d');if(!c||screen!=='world')return;c.imageSmoothingEnabled=false;const cw=c.canvas.width,ch=c.canvas.height;const zoom=cw<600?1.3:1.65;camera.x=Math.max(0,Math.min(W*T-cw/zoom,(state.x+.5)*T-cw/zoom/2));camera.y=Math.max(0,Math.min(H*T-ch/zoom,(state.y+.5)*T-ch/zoom/2));c.save();c.scale(zoom,zoom);c.translate(-camera.x,-camera.y);const minX=Math.max(0,Math.floor(camera.x/T)-1),maxX=Math.min(W,Math.ceil((camera.x+cw/zoom)/T)+1),minY=Math.max(0,Math.floor(camera.y/T)-3),maxY=Math.min(H,Math.ceil((camera.y+ch/zoom)/T)+2);for(let y=minY;y<maxY;y++)for(let x=minX;x<maxX;x++)drawTile(c,x,y,tile(x,y),frame);for(const p of POINTS){const x=p.x*T+16,y=p.y*T+16;if(p.id==='village'){rect(c,x-35,y-5,70,32,'#bbaf82');rect(c,x-41,y-11,82,8,'#4f6460');rect(c,x-30,y-24,60,14,'#617f73');rect(c,x-20,y-31,40,9,'#829181');rect(c,x-6,y+8,12,20,'#334d45');rect(c,x-28,y+4,12,12,'#dfc58e');rect(c,x+16,y+4,12,12,'#dfc58e');rect(c,x+39,y+25,12,5,'#c58d51');rect(c,x+43,y+13+Math.sin(frame/8)*2,5,13,'#e6c078')}else if(p.id.startsWith('chest')){rect(c,x-9,y+2,20,13,state.chests.includes(p.id)?'#605e47':'#b9a16a');rect(c,x-9,y+2,20,4,'#e0c58b');rect(c,x-2,y+5,4,6,'#5c614e')}else{const done=p.id==='keeper'?state.won:state.seals.includes(ENEMIES[p.id].boss);tower(c,x,y,1,p.id,done);if(!done){const yy=y-90+Math.sin(frame/25)*3;rect(c,x-3,yy,7,7,'#e6ce87');rect(c,x-1,yy-2,3,11,'#e6ce87')}}if(nearPoint()?.id===p.id){rect(c,x-9,y-100,20,15,'#192e2be6');c.fillStyle='#e4d4aa';c.font='10px monospace';c.fillText(wantsTouchControls()?'✦':'E',x-2,y-89)}}hero(c,state.x*T,state.y*T,frame);for(let i=0;i<12;i++){const fx=camera.x+(rng(i,4)*cw/zoom+Math.sin(frame/150+i)*20),fy=camera.y+rng(i,8)*ch/zoom;rect(c,fx,fy,2,2,'#d7d89d66')}c.restore();const v=c.createRadialGradient(cw/2,ch/2,ch*.15,cw/2,ch/2,cw*.8);v.addColorStop(0,'#0b202000');v.addColorStop(1,'#091c1e88');c.fillStyle=v;c.fillRect(0,0,cw,ch)}
function drawTitle(){const canvas=$('#title-canvas');if(!canvas)return;const c=canvas.getContext('2d');c.imageSmoothingEnabled=false;rect(c,0,0,640,720,'#19363a');const sky=c.createLinearGradient(0,0,0,720);sky.addColorStop(0,'#142c33');sky.addColorStop(.7,'#486b5e');sky.addColorStop(1,'#224842');c.fillStyle=sky;c.fillRect(0,0,640,720);c.fillStyle='#bdc2a0';c.beginPath();c.arc(390,145,56,0,Math.PI*2);c.fill();rect(c,346,99,6,90,'#9eae94');rect(c,347,142,92,5,'#9eae94');for(let i=0;i<70;i++){const x=rng(i,1)*640,y=rng(i,2)*350;rect(c,x,y,2,2,'#a6bba180')}for(let i=0;i<15;i++){const x=i*52-50,y=285+rng(i,3)*45;rect(c,x,y,75,300,'#294c47');rect(c,x+12,y-28,48,40,'#294c47')}rect(c,0,467,640,253,'#284d49');for(let i=0;i<35;i++)rect(c,rng(i,5)*640,480+rng(i,6)*240,30+rng(i,7)*50,2,'#41675a');for(let i=0;i<3;i++){rect(c,170+i*21,440+i*20,270-i*43,20,'#667b58')}rect(c,180,420,280,27,'#81916b');rect(c,205,387,230,40,'#5b7c59');rect(c,230,367,180,24,'#71926b');for(let i=0;i<9;i++)tree(c,170+rng(i,4)*270,340+rng(i,6)*100,i);tower(c,327,365,2.5,'keeper');rect(c,331,212,8,28,'#19363a');rect(c,338,196,17,7,'#19363a');for(let i=0;i<5;i++){rect(c,248+i*15,420+i*10,60,6,'#b3b18a')}tree(c,70,540,1);c.save();c.translate(10,455);c.scale(3,3);tree(c,0,0);c.restore();c.save();c.translate(560,420);c.scale(3,3);tree(c,0,0);c.restore();hero(c,288,415,0);for(let i=0;i<20;i++)rect(c,120+rng(i,11)*430,260+rng(i,13)*320,3,3,'#d0c88e88');const fog=c.createLinearGradient(0,580,0,720);fog.addColorStop(0,'#142a3000');fog.addColorStop(1,'#142a30');c.fillStyle=fog;c.fillRect(0,580,640,140)}
function drawEnemy(c,e){c.clearRect(0,0,96,96);const a=e.color,d='#34454c',light='#e2dfbb';if(e.kind==='wisp'){rect(c,28,22,40,43,a);rect(c,20,33,56,25,a);rect(c,34,13,27,58,a);rect(c,30,70,8,10,a);rect(c,53,70,8,8,a);rect(c,35,34,7,9,d);rect(c,55,34,7,9,d);rect(c,42,52,12,4,d);rect(c,37,21,9,5,light)}else if(e.kind==='wolf'){rect(c,18,38,58,28,a);rect(c,14,24,29,34,a);rect(c,14,15,9,22,a);rect(c,33,16,8,21,a);rect(c,6,44,23,15,a);rect(c,24,61,9,18,a);rect(c,59,60,9,19,a);rect(c,76,30,9,24,a);rect(c,23,36,5,5,'#e4d6a2');rect(c,6,44,7,6,d)}else if(e.kind==='tree'){tree(c,16,38,1);tree(c,47,32,2);rect(c,29,22,39,57,'#657452');rect(c,22,36,53,25,a);rect(c,34,11,30,24,a);rect(c,31,45,9,6,'#e9db91');rect(c,56,45,9,6,'#e9db91');rect(c,39,61,17,5,d);rect(c,22,77,17,8,'#657452');rect(c,58,77,16,8,'#657452')}else{const oracle=e.kind==='oracle',keeper=e.kind==='keeper';rect(c,31,20,34,54,a);rect(c,25,43,46,30,a);rect(c,20,70,56,10,a);rect(c,37,9,22,22,a);rect(c,40,20,16,5,d);rect(c,30,31,36,10,'#6e7881');rect(c,20,40,9,22,a);rect(c,67,40,9,22,a);rect(c,10,33,5,48,'#c4b584');rect(c,6,32,14,6,light);rect(c,40,39,17,23,d);rect(c,46,44,5,11,light);if(oracle){rect(c,26,4,7,16,light);rect(c,62,4,7,16,light);rect(c,12,13,13,11,light);rect(c,73,12,11,11,light)}if(keeper){c.strokeStyle=light;c.lineWidth=2;c.beginPath();c.arc(48,44,38,0,7);c.stroke();for(let i=0;i<12;i++){const t=i*Math.PI/6;rect(c,47+Math.sin(t)*36,43+Math.cos(t)*36,3,3,light)}}}rect(c,18,86,62,3,'#0e232955')}
function showMap(){if(!state)return;modal('The Stillwater Archipelago',`<div class="row between"><span class="eyebrow">An island outside time</span><span class="small muted">You are the golden dot</span></div><canvas id="map-canvas" class="map-image" width="736" height="544" aria-label="Island map"></canvas><div class="map-legend">${POINTS.filter(p=>!p.id.startsWith('chest')).map((p,i)=>`<span>${p.icon} ${i+1}. ${p.name}</span>`).join('')}</div><p class="small muted" style="margin-top:15px">Follow the pale roads to avoid encounters. Dark water and thick trees block your path.</p>`);const c=$('#map-canvas').getContext('2d');c.scale(.5,.5);for(let y=0;y<H;y++)for(let x=0;x<W;x++)drawTile(c,x,y,tile(x,y));for(const[p,i]of POINTS.map((p,i)=>[p,i])){rect(c,p.x*T+5,p.y*T+5,22,22,p.id.startsWith('chest')?'#c5b98c':'#e5d4a0');if(i<5){c.fillStyle='#152e2d';c.font='bold 18px sans-serif';c.fillText(String(i+1),p.x*T+11,p.y*T+23)}}c.fillStyle='#fbe7ad';c.beginPath();c.arc(state.x*T+16,state.y*T+16,13,0,7);c.fill();c.strokeStyle='#172c2b';c.lineWidth=5;c.stroke()}
function resize(){const c=$('#world');if(c){const box=c.parentElement.getBoundingClientRect();c.width=Math.max(300,Math.round(box.width));c.height=Math.max(200,Math.round(box.height));drawWorld()}}
function loop(t){frame++;if(state&&screen==='world'&&!modalStack.length&&!battle){if(t-lastMove>135){let dx=(keys.ArrowRight||keys.d?1:0)-(keys.ArrowLeft||keys.a?1:0),dy=(keys.ArrowDown||keys.s?1:0)-(keys.ArrowUp||keys.w?1:0);if(dx||dy){move(dx,dy);lastMove=t}}if(t-lastFrame>1000){state.playtime=(state.playtime||0)+1;lastFrame=t}}if(frame%2===0)drawWorld();animId=requestAnimationFrame(loop)}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const [act,arg,extra]=b.dataset.action.split(':');switch(act){case'info':modal(esc(b.dataset.title),`<p class="muted">${esc(b.dataset.text)}</p>`);break;case'new':selected=[];if(state&&screen==='world'){leave();break}creation();break;case'title':title();break;case'class':if(selected.length>=2)selected=[];selected.push(Number(arg));creation();break;case'reset-classes':selected=[];creation();break;case'begin':if(selected.length===2)begin();break;case'close':close();break;case'menu':menu();break;case'inventory':inventory();break;case'equipment':equipment();break;case'leveling':leveling();break;case'choose-ultimate':chooseUltimate(Number(arg),Number(extra));break;case'crafting':crafting();break;case'craft':craft(arg);break;case'bestiary':bestiary();break;case'save-menu':saveMenu();break;case'save':if(!battle)saveGame();break;case'load':loadGame();break;case'export':if(!battle)exportSave();break;case'import':if(!battle)importSave();break;case'leave':leave();break;case'interact':interact();break;case'map':showMap();break;case'help':help();break;case'fight':fight(arg,extra);break;case'battle-items':inventory();break;case'use':useItem(arg);break;case'buy':{const price={potion:12,ether:16,herb:5,ore:9,crystal:7}[arg];if(price&&state.gold>=price){state.gold-=price;state.items[arg]++;updateSidebar();close();shop();sound()}break}case'sound':audioOn=!audioOn;sound();b.textContent=`Sound ${audioOn?'on':'off'} ♫`;break;case'exit':dialogue('Until the next hour','Your journey will be here when you return. You can safely close this tab.',[{label:'Return to title',fn:title}]);break}});
document.addEventListener('keydown',e=>{if(e.target.matches('input,textarea'))return;const k=e.key.length===1?e.key.toLowerCase():e.key;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(k))e.preventDefault();if(k==='Tab'&&modalStack.length){const m=modalStack.at(-1),list=[...m.querySelectorAll('button:not(:disabled),input,a[href]')];if(e.shiftKey&&document.activeElement===list[0]){e.preventDefault();list.at(-1)?.focus()}else if(!e.shiftKey&&document.activeElement===list.at(-1)){e.preventDefault();list[0]?.focus()}}if(e.repeat&&['Escape','e','m'].includes(k))return;keys[k]=true;if(k==='Escape'){if(modalStack.length)close();else if(screen==='world')menu()}if(screen==='world'&&!modalStack.length){if(k==='e')interact();if(k==='m')showMap()}});
// Touch devices and narrow screens get a dedicated control dock, outside the map.
const touchMedia=window.matchMedia?.('(any-pointer: coarse), (max-width: 640px), (max-width: 960px) and (max-height: 500px)');
let touchTimer=null,touchPointer=null,touchButton=null;
function wantsTouchControls(){return !!touchMedia?.matches}
function updateInputMode(){document.documentElement?.classList.toggle('touch-mode',wantsTouchControls());stopTouchMove();resize()}
function mobileControls(){const dirs=[[-1,-1,'northwest','↖'],[0,-1,'north','↑'],[1,-1,'northeast','↗'],[-1,0,'west','←'],[0,0,'','✥'],[1,0,'east','→'],[-1,1,'southwest','↙'],[0,1,'south','↓'],[1,1,'southeast','↘']];return `<nav class="mobile-controls" aria-label="Touch game controls"><div class="direction-pad" role="group" aria-label="Movement">${dirs.map(([dx,dy,name,arrow])=>name?`<button data-move="${dx},${dy}" aria-label="Move ${name}">${arrow}</button>`:`<span class="pad-center" aria-hidden="true">${arrow}</span>`).join('')}</div><div class="touch-actions"><button class="btn primary touch-interact" data-action="interact" aria-label="Interact with nearby landmark"><span>Interact <span aria-hidden="true">✦</span></span><small data-touch-prompt>Near a landmark</small></button><button class="btn" data-action="map" aria-label="Open map">Map</button><button class="btn" data-action="menu" aria-label="Open game menu">☰ Menu</button></div></nav>`}
function updateTouchPrompt(){const prompt=$('[data-touch-prompt]');if(prompt)prompt.textContent=nearPoint()?.name||'Near a landmark'}
function stopTouchMove(){if(touchTimer!==null)clearInterval(touchTimer);touchTimer=null;touchPointer=null;touchButton?.classList.remove('pressed');touchButton=null}
function startTouchMove(e){const button=e.target.closest('[data-move]');if(!button||button.disabled||e.button>0||screen!=='world'||battle||modalStack.length||touchPointer!==null)return;e.preventDefault();const[dx,dy]=button.dataset.move.split(',').map(Number);touchPointer=e.pointerId;touchButton=button;button.classList.add('pressed');button.setPointerCapture?.(e.pointerId);move(dx,dy);if(battle||modalStack.length){stopTouchMove();return}touchTimer=setInterval(()=>{if(screen!=='world'||battle||modalStack.length){stopTouchMove();return}move(dx,dy)},150)}
function endTouchMove(e){if(e.pointerId===touchPointer)stopTouchMove()}
document.addEventListener('pointerdown',startTouchMove);
document.addEventListener('contextmenu',e=>{if(e.target.closest('.mobile-controls'))e.preventDefault()});
for(const event of ['pointerup','pointercancel','lostpointercapture'])document.addEventListener(event,endTouchMove);
document.addEventListener('keyup',e=>{keys[e.key.length===1?e.key.toLowerCase():e.key]=false});
window.addEventListener('blur',()=>{keys={};stopTouchMove()});
document.addEventListener('visibilitychange',()=>{keys={};stopTouchMove()});
window.addEventListener('resize',updateInputMode);
if(touchMedia?.addEventListener)touchMedia.addEventListener('change',updateInputMode);else touchMedia?.addListener?.(updateInputMode);
title();updateInputMode();requestAnimationFrame(loop);
